import 'package:dart_valkey/dart_valkey.dart';

Future<void> main() async {
  final client = ValkeyCommandClient(
    host: 'localhost',
    port: 6379,
  );

  await client.connect();
  await client.set('key', 'value');
  final value = await client.get('key');
  print('Value: $value');

  await client.close();
}
